\begin{aligned}\text{Z-Score} &= \frac{\bar{x}-\mu}{\sigma / \sqrt{n}} \\&= \frac{300-200}{5 / \sqrt{n}} \\&= \frac{100}{5 / \sqrt{n}} \\&= 20\sqrt{n}\end{aligned}

